'use strict';
(() => {
  const D = window.ATLAS_DATA;
  const $ = (s, root = document) => root.querySelector(s);
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num = (v,d=0) => Number(v).toLocaleString('en-IN',{minimumFractionDigits:d,maximumFractionDigits:d});
  const pct = (v,d=1) => `${v>0?'+':v<0?'−':''}${Math.abs(v).toFixed(d)}%`;
  const clamp = (v,a,b) => Math.min(b,Math.max(a,v));
  const dateAge = date => Math.max(0,(Date.parse(D.checked)-Date.parse(date))/(864e5*30.4375));
  const link = (key,label='Open source') => `<a href="${esc(D.sources[key].url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
  const badge = (text,color='') => `<span class="tag ${color}">${esc(text)}</span>`;
  const stat = (label,value,note,tag='') => `<div class="stat">${tag?`<span class="mini-badge">${esc(tag)}</span>`:''}<span class="stat-label">${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`;
  const S = {view:'explorer',geo:'india',query:'',sector:'all',evidence:'all',page:1,cityMetric:'housing',weight:70,citySort:'score',momentum:'all',maxAge:48,flow:'export',tradeQuery:'',tradeMin:-100,tradeSort:'value',labBusiness:'panipuri',lab:{buyers:1000,frequency:4,providers:20,capacity:150,shock:0,price:50,cost:25,fixed:30000,capture:10}};
  const viewInfo = {
    explorer:['Business explorer','India business explorer','Find a market worth investigating. Open any business to inspect its evidence.'],
    cities:['City comparison','Compare the markets','Compare like-for-like activity. Adjust the index to see how the ranking changes.'],
    momentum:['Growth & cooling','Follow the measured signals','Observed growth, published forecasts and weaker indicators, kept in context.'],
    trade:['Imports & exports','India’s trade flows','Explore cross-border trade by product and partner, using official annual figures.'],
    lab:['Demand lab','Test your business idea','Change the assumptions. See how demand, capacity and operating results respond.'],
    sources:['Sources & method','Know what is behind the numbers','Every published figure has a period, geographic scope and a source.']
  };
  function getCity(){return D.cities.find(c=>c.id===S.geo);}
  function geoName(){return S.geo==='india'?'All India':getCity()?.name || S.geo.replace(/^state:/,'');}
  function stateContext(){const c=getCity(); const name=S.geo.startsWith('state:')?S.geo.slice(6):c?.state; return D.consumption.find(r=>r[0]===name);}
  function pair(type, geo=S.geo){
    if(geo.startsWith('state:')) return null;
    const c=D.cities.find(x=>x.id===geo);
    const rows=c?[c]:D.cities;
    const housing=type==='housing';
    const demand=rows.reduce((a,r)=>a+(housing?r.sales:r.warehouseDemand),0);
    const supply=rows.reduce((a,r)=>a+(housing?r.launches:r.warehouseSupply),0);
    return {demand,supply,scope:c?c.name:'Eight tracked city markets',period:housing?'H1 2026':'H2 2025',date:housing?'2026-06-30':'2025-12-31',unit:housing?'homes':'million sq ft',source:housing?'housing':'logistics',demandLabel:housing?'Homes sold':'Leasing absorption',supplyLabel:housing?'New homes launched':'New space added',growth:housing?(c?c.growth:1):null,approx:!housing};
  }
  function record(b){
    if(['housing','warehouses'].includes(b.signal)){
      const p=pair(b.signal);
      if(p) return {...p,kind:'paired',demandText:`${p.approx?'≈':''}${num(p.demand,p.approx?1:0)}`,supplyText:`${p.approx?'≈':''}${num(p.supply,p.approx?1:0)}`,trend:p.growth<0?'cooling':'activity'};
    }
    const sig=D.signals[b.signal];
    if(sig && S.geo==='india') return {...sig,kind:sig.trend==='forecast'?'forecast':sig.trend==='proxy'?'proxy':'single',demandText:sig.demand || 'Not measured',supplyText:sig.supply || 'Not measured',demandLabel:sig.demandLabel,supplyLabel:sig.supplyLabel || 'Capacity unavailable'};
    return {kind:'missing',demandText:'Not measured',supplyText:'Not measured',demandLabel:'For this business and market',supplyLabel:'For this business and market',scope:geoName(),period:null,source:null,trend:'unknown',contextSignal:sig};
  }
  const evidenceLabel = r => ({paired:['Paired flows','blue'],forecast:['Published forecast','amber'],proxy:['Sector proxy','amber'],single:['One-sided evidence',''],missing:['Not enough data','']}[r.kind]);
  function options(list,value){return list.map(([v,l])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(l)}</option>`).join('');}
  function setupGeography(){
    $('#geography').innerHTML='<option value="india">All India</option><optgroup label="Major city markets">'+D.cities.map(c=>`<option value="${c.id}">${c.name}${c.id==='bengaluru'?' (Bangalore)':''}</option>`).join('')+'</optgroup><optgroup label="States & union territories">'+D.states.map(n=>`<option value="state:${esc(n)}">${esc(n)}</option>`).join('')+'</optgroup>';
  }
  function contextHTML(){
    if(S.geo==='india') return '<strong>National context + eight city markets.</strong> State spending profiles available for 18 major states. Missing data stays unscored.';
    const st=stateContext();
    if(st) return `<strong>${esc(st[0])} spending context:</strong> ₹${num(st[2])} urban / ₹${num(st[1])} rural, per person per month.<br><span class="micro">HCES 2023–24 · State averages${getCity()?' — not city measurements':''}. ${link('hces')}</span>`;
    if(S.geo==='delhi') return '<strong>Delhi NCR covers multiple jurisdictions.</strong> City-market figures follow the research publishers; no Delhi-only spending proxy is assigned.';
    return `<strong>${esc(geoName())}:</strong> This snapshot has no verified local sector counts or state spending row for this selection. National context remains available in each brief.`;
  }
  function render(){
    const info=viewInfo[S.view];
    $('#page-title').textContent=info[1];$('#page-description').textContent=info[2];$('#breadcrumb').textContent=info[0];
    document.querySelectorAll('.nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.view===S.view);b.setAttribute('aria-current',b.dataset.view===S.view?'page':'false');});
    $('#global-controls').classList.toggle('hidden',['sources','trade','momentum'].includes(S.view));
    $('#geography').value=S.geo;$('#geo-context').innerHTML=contextHTML();
    $('#export-data').textContent=S.view==='lab'?'Export this scenario':S.view==='sources'?'Export research data':'Export visible data';
    const renderer={explorer:renderExplorer,cities:renderCities,momentum:renderMomentum,trade:renderTrade,lab:renderLab,sources:renderSources};
    $('#view-root').innerHTML=renderer[S.view]();
    if(S.view==='explorer')renderBusinessRows();
    if(S.view==='cities')renderCityRows();
    if(S.view==='momentum')renderSignalCards();
    if(S.view==='trade')renderTradeRows();
    if(S.view==='lab')updateLabResult();
  }
  function navigate(view){if(!viewInfo[view])return;S.view=view;location.hash=view;render();window.scrollTo({top:0,behavior:'instant'});}
  function barChart(type='housing'){
    const housing=type==='housing';const max=Math.max(...D.cities.map(c=>Math.max(housing?c.sales:c.warehouseDemand,housing?c.launches:c.warehouseSupply)));
    const rows=[...D.cities].sort((a,b)=>(housing?b.sales:b.warehouseDemand)-(housing?a.sales:a.warehouseDemand));
    return `<div class="legend"><span><i></i>${housing?'Homes sold':'Space leased'}</span><span><i class="pale"></i>${housing?'New launches':'New space added'}</span><span>Right: transactions / additions</span></div><div class="city-bars">${rows.map(c=>{const d=housing?c.sales:c.warehouseDemand,s=housing?c.launches:c.warehouseSupply;return `<div class="city-row"><button class="city-label" data-city="${c.id}" title="Select ${c.name}">${c.name}</button><div class="bar-track" role="img" aria-label="${c.name}: ${num(d,housing?0:1)} ${housing?'homes sold':'million sq ft leased'}, ${num(s,housing?0:1)} ${housing?'new launches':'million sq ft added'}"><div class="bar-sales" style="width:${d/max*100}%"></div><div class="bar-supply" style="width:${s/max*100}%"></div></div><span class="bar-ratio">${(d/s).toFixed(2)}×</span></div>`;}).join('')}</div><p class="chart-note">${housing?'H1 2026 · Housing units':'H2 2025 · Approximate million sq ft'}. Existing inventory is excluded from new additions. A ratio above 1 does not establish unmet demand. ${link(housing?'housing':'logistics')}</p>`;
  }
  function renderExplorer(){
    const localPairs=D.businesses.filter(b=>record(b).kind==='paired').length;
    return `<div class="stats">${stat('Business models',D.businesses.length,'Across '+Object.keys(D.sectors).length+' sectors','EXPLORE')}${stat('Comparable city sectors',localPairs,'Housing and warehousing','EVIDENCE')}${stat('Major city markets','8','Including your five target cities')}${stat('Source publications',Object.keys(D.sources).length,'Dated, linked and explained')}</div>
    <div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Where transactions meet new supply</h2><p>Eight city markets · same-period comparisons</p></div><select class="control" id="chart-metric" aria-label="Chart market">${options([['housing','Housing'],['warehouses','Warehousing']],S.cityMetric)}</select></div><div class="panel-body">${barChart(S.cityMetric)}</div></section>
    <section class="panel"><div class="panel-head"><div><h2>Signals to investigate</h2><p>National indicators · different measures and periods</p></div>${badge('SOURCE LED','blue')}</div><div class="panel-body">
      <div class="signal-item"><span class="signal-icon" aria-hidden="true">↗</span><div><div class="signal-title">Electric two-wheeler sales</div><div class="signal-sub">FY 2024–25 · observed sales</div></div><div class="signal-value green-text">+21.2%<small>year on year</small></div></div>
      <div class="signal-item"><span class="signal-icon" aria-hidden="true">↗</span><div><div class="signal-title">Fitness facility revenue</div><div class="signal-sub">2024–30 · published forecast</div></div><div class="signal-value">15%<small>forecast CAGR</small></div></div>
      <div class="signal-item"><span class="signal-icon red" aria-hidden="true">↘</span><div><div class="signal-title">Pay DTH subscriptions</div><div class="signal-sub">March 2026 · observed base</div></div><div class="signal-value red-text">−13.8%<small>year on year</small></div></div>
      <div class="insight-note">Growth can coexist with intense competition. Open the source and check local capacity before calling it an opportunity.</div><button class="text-button" data-view="momentum">Explore growth and cooling</button>
    </div></section></div>
    ${S.geo.startsWith('state:')?renderStateContext():''}
    <section class="panel"><div class="panel-head"><div><h2>Explore businesses in ${esc(geoName())}</h2><p>Demand and supply retain their units. Unverified categories have no fabricated score.</p></div><span class="tag" id="result-count"></span></div>
    <div class="explorer-toolbar"><div class="search-wrap"><span class="search-symbol" aria-hidden="true">⌕</span><input type="search" class="control" id="business-search" placeholder="Search panipuri, protein, pickleball…" aria-label="Search businesses" value="${esc(S.query)}"></div><select class="control" id="sector-filter" aria-label="Filter sector">${options([['all','All sectors'],...Object.entries(D.sectors).map(([k,v])=>[k,v.name])],S.sector)}</select><select class="control" id="evidence-filter" aria-label="Filter evidence">${options([['all','All evidence'],['paired','Paired flows'],['published','Published indicator'],['missing','Needs local research']],S.evidence)}</select></div>
    <div class="table-wrap"><table><thead><tr><th>Business</th><th>Demand indicator</th><th>Supply indicator</th><th>Evidence</th><th></th></tr></thead><tbody id="business-rows"></tbody></table></div><div class="table-bottom"><span id="page-info"></span><div class="pagination"><button id="previous-page">Previous</button><span id="page-number"></span><button id="next-page">Next</button></div></div></section>
    <div class="coverage-note"><span aria-hidden="true">ⓘ</span><div><b>Snapshot, not a live market census.</b> No live sensors, point-of-sale feeds, restaurant occupancy, court booking feeds or private inventory systems are connected. Open a business to see the evidence and the local measurements it still needs.</div></div>`;
  }
  function filteredBusinesses(){return D.businesses.filter(b=>{
    const words=`${b.name} ${D.sectors[b.sector].name} ${b.id==='panipuri'?'pani puri gol gappa puchka':''} ${b.id==='bengaluru'?'bangalore':''}`.toLowerCase();
    const kind=record(b).kind;
    return words.includes(S.query.toLowerCase().trim())&&(S.sector==='all'||b.sector===S.sector)&&(S.evidence==='all'||(S.evidence==='published'&&kind!=='missing')||S.evidence===kind);
  }).sort((a,b)=>{const k={paired:0,single:1,forecast:2,proxy:3,missing:4};return k[record(a).kind]-k[record(b).kind]||a.name.localeCompare(b.name);});}
  function renderBusinessRows(){
    const rows=filteredBusinesses(),pages=Math.max(1,Math.ceil(rows.length/10));S.page=clamp(S.page,1,pages);
    $('#result-count').textContent=rows.length+' models';
    $('#business-rows').innerHTML=rows.slice((S.page-1)*10,S.page*10).map(b=>{const r=record(b),[t,c]=evidenceLabel(r);return `<tr><td><div class="business-cell"><span class="business-icon" aria-hidden="true">${D.sectors[b.sector].code}</span><div><button class="business-name" data-detail="${b.id}">${esc(b.name)}</button><small>${esc(D.sectors[b.sector].name)}</small></div></div></td><td><span class="metric-number">${esc(r.demandText)}</span><small>${esc(r.demandLabel)}${r.kind==='paired'?' · '+r.unit:''}</small></td><td><span class="metric-number">${esc(r.supplyText)}</span><small>${esc(r.supplyLabel)}${r.kind==='paired'?' · '+r.unit:''}</small></td><td>${badge(t,c)}<small>${esc(r.period||'Local evidence needed')}${r.kind!=='missing'?'<br>'+esc(r.scope):''}</small></td><td><button class="text-button" data-detail="${b.id}" aria-label="Open ${esc(b.name)} brief">View</button></td></tr>`;}).join('')||'<tr><td colspan="5"><div class="empty"><h3>No matching businesses</h3><p>Try another word or remove a sector or evidence filter.</p><button class="button light" id="reset-filters">Reset filters</button></div></td></tr>';
    $('#page-info').textContent=rows.length?`${(S.page-1)*10+1}–${Math.min(S.page*10,rows.length)} of ${rows.length} businesses`:'0 businesses';
    $('#page-number').textContent=`${S.page} / ${pages}`;$('#previous-page').disabled=S.page<=1;$('#next-page').disabled=S.page>=pages;
  }
  function renderStateContext(){
    const st=stateContext();
    if(!st)return `<div class="coverage-note"><div><b>No state-level observation loaded for ${esc(geoName())}.</b> This is missing coverage, not zero demand. Use the Demand lab for local assumptions, or open national source evidence.</div></div>`;
    return `<section class="panel wide-panel"><div class="panel-head"><div><h2>${esc(st[0])}: household spending context</h2><p>HCES 2023–24 · historical monthly expenditure per person</p></div>${badge('Survey estimate','blue')}</div><div class="panel-body"><div class="state-bars"><div><small>Rural MPCE</small><b>₹${num(st[1])}</b></div><div><small>Urban MPCE</small><b>₹${num(st[2])}</b></div></div><p class="chart-note">Current-price consumption, excluding imputed social transfers. It is not household income or demand for a particular product. ${link('hces')}</p></div></section>`;
  }
  function activityScore(c){const h=S.cityMetric==='housing',d=h?c.sales:c.warehouseDemand,s=h?c.launches:c.warehouseSupply;const balance=100*d/(d+s),growth=clamp(50+2*c.growth,0,100);return h?(S.weight*balance+(100-S.weight)*growth)/100:balance;}
  function sortedCities(){return [...D.cities].sort((a,b)=>S.citySort==='alpha'?a.name.localeCompare(b.name):S.citySort==='demand'?((S.cityMetric==='housing'?b.sales:b.warehouseDemand)-(S.cityMetric==='housing'?a.sales:a.warehouseDemand)):activityScore(b)-activityScore(a));}
  function renderCities(){
    const h=S.cityMetric==='housing';
    return `<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>${h?'Housing sales & launches':'Warehousing absorption & additions'}</h2><p>${h?'January–June 2026 · housing units':'July–December 2025 · approximate million sq ft'}</p></div></div><div class="panel-body"><div class="segmented"><button class="${h?'active':''}" data-city-metric="housing">Housing</button><button class="${!h?'active':''}" data-city-metric="warehouses">Warehousing</button></div><div class="market-note">${barChart(S.cityMetric)}</div></div></section><section class="panel"><div class="panel-head"><div><h2>Define your activity index</h2><p>A transparent comparison, not a profit prediction.</p></div>${badge('0–100','blue')}</div><div class="panel-body">${h?`<div class="range-group"><label class="range-label" for="index-weight"><span>Weight on transaction / addition balance</span><output id="weight-value">${S.weight}%</output></label><input id="index-weight" type="range" min="0" max="100" step="5" value="${S.weight}"><small>Remaining weight goes to year-on-year sales growth.</small></div>`:'<p class="micro">Only the transaction / addition balance is scored. A comparable city growth series is not loaded.</p>'}<div class="formula">Balance = 100 × transactions ÷ (transactions + new additions)${h?'<br>Growth = clamp(50 + 2 × sales YoY %, 0, 100)<br>Index = weighted average of Balance and Growth':''}</div><p class="chart-note">Higher scores describe stronger transaction activity relative to new additions. Existing stock, prices and business costs are not included. The weights and growth scaling are choices made by this tool, not an official rating.</p><div class="insight-note">No score is assigned to panipuri, protein bars, pickleball or other markets without comparable local evidence.</div></div></section></div>
      <section class="panel wide-panel"><div class="panel-head"><div><h2>Eight-city comparison</h2><p>${S.geo==='india'?'All tracked markets':esc(geoName())+' is highlighted where covered; all eight markets remain visible.'}</p></div><select id="city-sort" class="control" aria-label="Sort cities">${options([['score','Activity index'],['demand','Transaction volume'],['alpha','City name']],S.citySort)}</select></div><div class="table-wrap"><table><thead><tr><th>City market</th><th>${h?'Homes sold':'Space leased'}</th><th>${h?'New launches':'New space added'}</th><th>Transaction / addition</th><th>${h?'Sales YoY':'Precision'}</th><th>Activity index</th></tr></thead><tbody id="city-rows"></tbody></table></div><div class="table-bottom"><span>${h?'Source: Knight Frank · H1 2026':'Source: CBRE · H2 2025 · million sq ft'} · ${link(h?'housing':'logistics')}</span></div></section>
      <section class="panel"><div class="panel-head"><div><h2>Beyond the metros: state spending</h2><p>Rural and urban markets · HCES 2023–24 · ₹ per person per month</p></div>${badge('18 states')}</div><div class="panel-body"><p class="chart-note no-margin">State expenditure helps frame affordability; it does not establish business-level demand. Other states and territories remain selectable with missing coverage clearly shown. ${link('hces')}</p></div><div class="table-wrap"><table class="state-table"><thead><tr><th>State</th><th>Rural MPCE</th><th>Urban MPCE</th><th></th></tr></thead><tbody>${[...D.consumption].sort((a,b)=>b[2]-a[2]).map(r=>`<tr><td>${esc(r[0])}</td><td>₹${num(r[1])}</td><td>₹${num(r[2])}</td><td><button class="text-button" data-state="${esc(r[0])}">Explore</button></td></tr>`).join('')}</tbody></table></div></section>`;
  }
  function renderCityRows(){const h=S.cityMetric==='housing';$('#city-rows').innerHTML=sortedCities().map(c=>{const d=h?c.sales:c.warehouseDemand,s=h?c.launches:c.warehouseSupply,score=activityScore(c);return `<tr ${S.geo===c.id?'style="background:#f3f5ff"':''}><td><button class="business-name" data-city="${c.id}">${c.name}</button>${S.geo===c.id?'<small>Selected market</small>':''}</td><td class="metric-number">${!h?'≈':''}${num(d,h?0:1)}</td><td>${!h?'≈':''}${num(s,h?0:1)}</td><td>${(d/s).toFixed(2)}×</td><td>${h?badge(pct(c.growth,0),c.growth<0?'red':'green'):badge('Approximate')}</td><td><span class="score"><b>${score.toFixed(1)}</b><span class="score-track"><i style="width:${score}%"></i></span></span></td></tr>`;}).join('');}
  function signalList(){
    return Object.entries(D.signals).map(([id,r])=>({id,...r})).concat([{id:'ncr',title:'Delhi NCR home sales',demand:'24,862 homes sold',display:'−7%',trend:'cooling',value:-7,source:'housing',period:'H1 2026 versus H1 2025',date:'2026-06-30',scope:'Delhi NCR',note:'Year-on-year sales decline in a tracked property market. Price mix and existing inventory also matter; this is not evidence that the market is ending.'}]).filter(r=>dateAge(r.date)<=S.maxAge&&(S.momentum==='all'||(S.momentum==='observed'&&['growing','cooling'].includes(r.trend))||(S.momentum==='forecast'&&r.trend==='forecast')||(S.momentum==='cooling'&&r.trend==='cooling')));
  }
  function renderMomentum(){return `<div class="coverage-note"><div><b>National signals and one city decline example.</b> These measures use different units and time periods, so they are not combined into a universal “best business” score. Falling activity does not prove a field will disappear.</div></div><section class="panel"><div class="panel-head"><div><h2>Choose the evidence you want to see</h2><p>Historical measurements and forecasts have different meanings.</p></div></div><div class="panel-body"><div class="segmented">${[['all','All signals'],['observed','Observed change'],['forecast','Forecasts'],['cooling','Cooling']].map(([v,l])=>`<button data-momentum="${v}" class="${S.momentum===v?'active':''}">${l}</button>`).join('')}</div><div class="range-group"><label class="range-label" for="max-age"><span>Maximum age of the observation or forecast baseline</span><output id="age-value">${S.maxAge} months</output></label><input type="range" id="max-age" min="6" max="60" step="6" value="${S.maxAge}"><small>Age is calculated as of 05 October 2026. A recent publication can contain older data.</small></div></div></section><div class="card-grid" id="signal-cards"></div>`;}
  function renderSignalCards(){const rows=signalList();$('#signal-cards').innerHTML=rows.map(r=>{const cooling=r.trend==='cooling',forecast=r.trend==='forecast';const kind=forecast?'Forecast':r.trend==='proxy'?'Relative growth proxy':r.trend==='context'?'Supply context':'Observed change';return `<article class="panel trend-card ${cooling?'cool':''}">${badge(kind,cooling?'red':forecast||r.trend==='proxy'?'amber':'blue')}<h3>${esc(r.title)}</h3><strong class="big ${cooling?'red-text':r.trend==='growing'?'green-text':''}">${esc(r.display)}</strong><div class="period">${esc(r.period)} · ${esc(r.scope)}</div><p>${esc(r.note)}</p>${link(r.source)}<div class="source-meta">Publisher: ${esc(D.sources[r.source].publisher)}</div></article>`;}).join('')||'<div class="panel empty"><h3>No signals meet this filter</h3><p>Increase the maximum age or select a different evidence type.</p></div>';}
  function renderTrade(){const t=D.trade.totals;return `<div class="stats">${stat('Merchandise exports · US$',num(t.merchandiseExports,2)+'bn','FY 2025–26 · goods only')}${stat('Merchandise imports · US$',num(t.merchandiseImports,2)+'bn','FY 2025–26 · goods only')}${stat('Goods trade balance · US$','−'+num(t.merchandiseImports-t.merchandiseExports,2)+'bn','Calculated from rounded totals')}${stat('Services exports · US$',num(t.servicesExports,2)+'bn','Includes estimated March services','ESTIMATE')}</div>
    <div class="coverage-note"><div><b>India-wide customs and trade figures.</b> Annual comparison: April 2025–March 2026 versus April 2024–March 2025. Release vintage: 15 April 2026; subject to revision. These are trade values, not city consumption or unserved orders. ${link('trade')}</div></div>
    <div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Products crossing the border</h2><p>Selected commodity groups · values in US$ billion</p></div></div><div class="panel-body"><div class="segmented"><button data-flow="export" class="${S.flow==='export'?'active':''}">Exports from India</button><button data-flow="import" class="${S.flow==='import'?'active':''}">Imports into India</button></div><div class="controls-row"><input class="control" id="trade-search" type="search" placeholder="Search a commodity" aria-label="Search trade commodity" value="${esc(S.tradeQuery)}"><select class="control" id="trade-sort" aria-label="Sort trade products">${options([['value','Largest trade value'],['growth','Highest growth'],['decline','Largest decline']],S.tradeSort)}</select></div><div class="range-group"><label class="range-label" for="trade-min"><span>Minimum annual value growth</span><output id="trade-min-value">${S.tradeMin===-100?'Show all':pct(S.tradeMin,0)}</output></label><input type="range" id="trade-min" min="-100" max="100" step="5" value="${S.tradeMin}"><small>Nominal USD value growth can reflect price and exchange-rate changes, not just volume.</small></div></div></section>
    <section class="panel"><div class="panel-head"><div><h2>Read a trade signal carefully</h2><p>Business demand starts with a specific buyer.</p></div></div><div class="panel-body"><p class="micro">A high import value can identify a market to investigate. It does not prove domestic supply is inadequate or that replacing imports is commercially viable.</p><p class="micro">Export growth shows recorded cross-border activity. Check buyer specifications, tariffs, freight, payment terms and market access before testing a product.</p><div class="insight-note">No product-by-country volumes are inferred from these separate tables. No city trade allocation is invented.</div><button class="text-button" data-trade-model="tradeagency">Test a trading business in the Demand lab</button></div></section></div>
    <section class="panel wide-panel"><div class="panel-head"><div><h2 id="trade-table-title"></h2><p>Selected groups, not a complete commodity list. ${link('tradeTables')}</p></div><span id="trade-count" class="tag"></span></div><div class="table-wrap"><table><thead><tr><th>Commodity group</th><th>FY 2024–25</th><th>FY 2025–26</th><th>Value growth</th></tr></thead><tbody id="trade-rows"></tbody></table></div></section>
    <section class="panel"><div class="panel-head"><div><h2>Selected trading partners</h2><p>All commodities combined per country · US$ billion · same annual periods</p></div></div><div class="table-wrap"><table><thead><tr><th id="partner-label"></th><th>FY 2024–25</th><th>FY 2025–26</th><th>Value growth</th></tr></thead><tbody id="partner-rows"></tbody></table></div><div class="table-bottom"><span>Partners are not filtered by the commodity search. ${link('tradeTables')}</span></div></section>`;}
  function tradeRows(){return D.trade.products.filter(r=>r[0]===S.flow&&r[1].toLowerCase().includes(S.tradeQuery.toLowerCase().trim())&&(r[3]/r[2]-1)*100>=S.tradeMin).sort((a,b)=>S.tradeSort==='value'?b[3]-a[3]:(S.tradeSort==='growth'?1:-1)*((b[3]/b[2])-(a[3]/a[2])));}
  function tradeTR(r){const g=(r[3]/r[2]-1)*100;return `<tr><td><b>${esc(r[1])}</b></td><td>${num(r[2]/1000,2)}</td><td class="metric-number">${num(r[3]/1000,2)}</td><td>${badge(pct(g,2),g<0?'red':'green')}</td></tr>`;}
  function renderTradeRows(){const rows=tradeRows();$('#trade-table-title').textContent=S.flow==='export'?'Export product signals':'Import product signals';$('#trade-count').textContent=rows.length+' of 8 selected groups';$('#trade-rows').innerHTML=rows.map(tradeTR).join('')||'<tr><td colspan="4"><div class="empty"><h3>No commodities meet the filter</h3><p>Reduce the growth threshold or change your search.</p></div></td></tr>';$('#partner-label').textContent=S.flow==='export'?'Export destination':'Import origin';$('#partner-rows').innerHTML=D.trade.partners.filter(r=>r[0]===S.flow).map(tradeTR).join('');}
  function labField(key,label,min,max,step,help){return `<div class="range-group"><label class="range-label" for="lab-${key}"><span>${label}</span><output id="value-${key}">${num(S.lab[key],step<1?1:0)}${['shock','capture'].includes(key)?'%':''}</output></label><input type="range" id="lab-${key}" data-lab="${key}" min="${min}" max="${max}" step="${step}" value="${S.lab[key]}"><small>${help}</small></div>`;}
  function renderLab(){const b=D.businesses.find(x=>x.id===S.labBusiness);return `<div class="lab-alert"><b>Illustrative scenario — not measured market data.</b> Starting values are examples. Replace them with your own survey, order and capacity evidence. Changing the city does not make these assumptions city statistics.</div><div class="lab-grid"><section class="panel lab-inputs"><h2>Your assumptions</h2><label class="field"><span>Business model</span><select id="lab-business">${options(D.businesses.map(x=>[x.id,x.name]),S.labBusiness)}</select></label><p class="micro" style="margin:12px 0 0">Market: <b>${esc(geoName())}</b> · matching unit: <b>${esc(b.unit)}</b> per month</p>
    ${labField('buyers','Monthly buyers / booking groups',0,20000,100,'Count paying buyers or booking groups within the catchment.')}
    ${labField('frequency',`${esc(b.unit)} per buyer / group`,0,30,0.5,'Use the same service or product unit for demand and capacity.')}
    ${labField('providers','Existing competing providers',0,200,1,'Include informal and online competitors serving this area.')}
    ${labField('capacity',`${esc(b.unit)} per provider / month`,0,3000,10,'Effective sustainable capacity, allowing for downtime.')}
    ${labField('shock','Demand change to test',-80,100,5,'A sensitivity assumption, not a market forecast.')}
    <button class="button light" id="reset-lab">Reset example values</button></section>
    <div><section class="panel lab-result"><div class="kicker">SCENARIO RESULT · MONTHLY</div><div id="lab-result" aria-live="polite"></div></section>
    <section class="panel lab-inputs" style="margin-top:20px"><h2>Can one business support its costs?</h2><p class="micro">A separate unit-economics check. Customer capture is your assumption.</p>${labField('capture','Your share of scenario demand',0,100,1,'This does not assume that every unit of unmet demand becomes your sale.')}
    <div class="lab-unit-grid"><label class="field"><span>Price per ${esc(b.unit)} · ₹</span><input class="lab-number" id="lab-price" data-money="price" type="number" min="0" max="1000000000" step="1" value="${S.lab.price}"></label><label class="field"><span>Variable cost per unit · ₹</span><input class="lab-number" id="lab-cost" data-money="cost" type="number" min="0" max="1000000000" step="1" value="${S.lab.cost}"></label></div><label class="field"><span>Monthly fixed operating costs · ₹</span><input class="lab-number" id="lab-fixed" data-money="fixed" type="number" min="0" max="1000000000" step="100" value="${S.lab.fixed}"></label><div id="economics-result" style="margin-top:20px" aria-live="polite"></div><p class="chart-note">Excludes financing, taxes, capital expenditure and new entrants. Your own supply capacity is not modelled; cap sales manually if needed. For trade, enter values in INR per shipment and include all variable landed costs.</p></section></div></div>`;}
  function calculateLab(l=S.lab){const demand=l.buyers*l.frequency*(1+l.shock/100),supply=l.providers*l.capacity,gap=demand-supply,capture=demand*l.capture/100,contribution=l.price-l.cost,profit=capture*contribution-l.fixed;return {demand,supply,gap,capture,contribution,profit,breakEven:contribution>0?l.fixed/contribution:null,ratio:supply>0?demand/supply:null};}
  function updateLabResult(){const r=calculateLab(),b=D.businesses.find(x=>x.id===S.labBusiness),max=Math.max(r.demand,r.supply,1),balanced=Math.abs(r.gap)<.00001;const label=balanced?'Demand matches capacity':r.gap>0?'Demand above existing capacity':'Capacity above demand';$('#lab-result').innerHTML=`<div class="big ${balanced?'':r.gap>0?'green-text':'red-text'}">${num(Math.abs(r.gap))} <span style="font-size:17px;letter-spacing:0;font-weight:500">${esc(b.unit)}</span></div><div class="sub">${label} under your assumptions.</div><div class="capacity-visual"><label>Modelled demand <b>${num(r.demand)}</b></label><div class="capacity-bar"><i style="width:${r.demand/max*100}%"></i></div><label>Existing capacity <b>${num(r.supply)}</b></label><div class="capacity-bar supply"><i style="width:${r.supply/max*100}%"></i></div></div><div class="lab-kpis"><div><strong>${r.ratio===null?'Undefined':r.ratio.toFixed(2)+'×'}</strong><small>Demand / capacity${r.supply===0?' · zero capacity':''}</small></div><div><strong>${num(r.capture)}</strong><small>Your assumed monthly sales units</small></div></div><div class="formula">Demand = buyers × units per buyer × (1 + demand change)<br>Capacity = providers × units per provider<br>Gap = demand − capacity</div><p class="chart-note">Potential unmet volume depends on your inputs, time period, price and catchment. Competitor responses and substitutions can change the result.</p>`;$('#economics-result').innerHTML=`<div class="lab-kpis"><div><strong class="${r.profit<0?'red-text':'green-text'}">${r.profit<0?'−':''}₹${num(Math.abs(r.profit))}</strong><small>Monthly operating ${r.profit<0?'loss':'surplus'} under assumptions</small></div><div><strong>${r.breakEven===null?'Not attainable':num(Math.ceil(r.breakEven))}</strong><small>Break-even units / month${r.contribution<=0?' · price does not exceed variable cost':''}</small></div></div>`;}
  function renderSources(){return `<div class="stats">${stat('Primary publications',Object.keys(D.sources).length,'Government and original research')}${stat('City pairs','16','2 sectors × 8 city markets')}${stat('State spending profiles','18','Historical survey observations')}${stat('Live feeds','0','Curated snapshot; manual updates')}</div>
    <div class="method-grid wide-panel"><section class="panel method-block"><h2>What the labels mean</h2><ul><li><b>Paired flows:</b> transactions and new additions, with matched units, period and publisher boundaries. Existing stock is excluded.</li><li><b>One-sided evidence:</b> a demand/activity or supply indicator; the other side is missing or not comparable.</li><li><b>Published forecast:</b> a research projection, with no claim that it has happened.</li><li><b>Sector proxy:</b> indirect context, not a measurement of the exact business.</li><li><b>Not enough data:</b> no defensible local demand/supply number in this snapshot. Missing is never treated as zero.</li></ul></section>
    <section class="panel method-block"><h2>How scores are calculated</h2><p class="micro">Only the City comparison has an activity index. It ranks comparable flows within one sector, not the probability of business success.</p><div class="formula">Flow balance = 100 × D / (D + S)<br>Housing growth component = clamp(50 + 2 × YoY %, 0, 100)<br>Housing index = w × balance + (1 − w) × growth<br>Warehousing index = balance</div><p class="micro">D is sales or leasing; S is new launches or additions. w comes from your slider. The chosen scaling and weights are heuristics. No universal opportunity rating, profit forecast or confidence percentage is manufactured.</p></section></div>
    <section class="panel method-block wide-panel"><h2>Coverage and limitations</h2><div class="method-grid"><div><h3>What is measured here</h3><p class="micro">Housing and warehousing activity in eight metros; spending context for 18 states; selected national sector signals; selected official imports, exports and trade partners. Delhi NCR is not Delhi city. National and state values are never distributed to cities using invented population weights.</p><p class="micro">Realised purchases can miss price-sensitive or unserved demand. Business counts are not capacity. A high transaction-to-new-supply ratio can coexist with available old inventory.</p></div><div><h3>What requires more data</h3><p class="micro">Local outlet capacity, hospital waiting lists, court bookings, SKU sales, repeat customers, private production and inventory feeds. Searches and map listings alone cannot fill these gaps. No “ending industry” prediction is made from one falling indicator.</p><p class="micro">This site contains no continuous data collection, paid API, scraping process or automatic refresh. The research-check date does not change when the page opens.</p></div></div></section>
    <div class="source-grid">${Object.entries(D.sources).map(([id,s])=>`<article class="panel source-card" id="source-${id}">${badge(s.type,'blue')}<h3>${esc(s.title)}</h3><p>${esc(s.publisher)}</p><div class="source-meta"><b>Period:</b> ${esc(s.period)}<br><b>Published:</b> ${esc(s.published)} · <b>Checked:</b> 05 Oct 2026<br><b>Coverage:</b> ${esc(s.coverage)}<br><b>Location:</b> ${esc(s.locator)}</div><p style="margin-top:13px">${esc(s.note)}</p>${link(id,'Read original publication')}</article>`).join('')}</div>`;}
  function showDetail(id){
    const b=D.businesses.find(x=>x.id===id);if(!b)return;
    const r=record(b),sector=D.sectors[b.sector],[label,color]=evidenceLabel(r),sig=D.signals[b.signal];
    let sources=[...new Set([r.source,sig?.source,...sector.sources].filter(Boolean))];
    let evidence='';
    if(r.kind==='paired')evidence=`<div class="evidence-line"><b>${esc(r.scope)} · ${esc(r.period)}</b><p>${esc(r.demandLabel)}: ${esc(r.demandText)} ${esc(r.unit)}. ${esc(r.supplyLabel)}: ${esc(r.supplyText)} ${esc(r.unit)}.</p><p>Transaction / new-addition ratio: <b>${(r.demand/r.supply).toFixed(2)}×</b>. It measures flow balance; total available supply and unmet demand remain unknown.</p>${link(r.source)}</div>`;
    else if(sig)evidence=`<div class="evidence-line"><b>${S.geo!=='india'?'National context only · ':''}${esc(sig.title)}</b><p>${esc(sig.demand||sig.supply)} · ${esc(sig.period)} · ${esc(sig.scope)}</p><p>${esc(sig.note)}</p>${link(sig.source)}</div>`;
    else evidence='<p>No verified business-specific local demand and capacity pair is loaded. The publications below are background context, not a numeric estimate for this category.</p>';
    if(b.id==='proteinbars'||b.id==='proteinpowder')evidence+='<div class="insight-note">Healthy-meal order growth and fitness forecasts do not measure protein-bar or protein-powder sales. Validate pack sales and repeat purchasing at your intended price.</div>';
    if(b.id==='pickleball'||b.id==='cricket')evidence+='<div class="insight-note">Broad sports-market revenue or fan counts do not tell us how many paid court-hours are needed in this city. The city-specific gap remains unknown.</div>';
    if(b.sector==='trade')evidence+='<div class="insight-note">The Imports & exports view contains actual national trade flows. These do not establish local buyer orders or supplier capacity for your business.</div>';
    const age=r.date?dateAge(r.date):sig?dateAge(sig.date):null;
    $('#detail-content').innerHTML=`<h1 id="detail-title">${esc(b.name)}</h1><p>${esc(geoName())} · ${esc(sector.name)}</p>${badge(label,color)}${age!==null?` <span class="data-age">Observation / baseline age: ${Math.floor(age)} months</span>`:''}<div class="brief-grid"><div class="brief-metric"><small>Demand indicator</small><strong>${esc(r.demandText)}</strong><p>${esc(r.demandLabel)}${r.kind==='paired'?' · '+esc(r.unit):''}</p></div><div class="brief-metric"><small>Supply indicator</small><strong>${esc(r.supplyText)}</strong><p>${esc(r.supplyLabel)}${r.kind==='paired'?' · '+esc(r.unit):''}</p></div></div><div class="details-section"><h3>What the evidence supports</h3>${evidence}</div><div class="details-section"><h3>What to measure locally</h3><p><b>Demand:</b> ${esc(sector.demand)}.</p><p><b>Supply:</b> ${esc(sector.supply)}.</p><ol class="checklist">${sector.checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div><div class="details-section"><h3>Source publications</h3>${sources.map(k=>`<div class="evidence-line">${link(k,D.sources[k].title)}<p>${esc(D.sources[k].period)} · ${esc(D.sources[k].coverage)}</p></div>`).join('')}</div><div class="dialog-actions">${b.sector==='trade'?'<button class="button light" data-view="trade">View trade flows</button>':''}<button class="button" data-lab-business="${b.id}">Model this business</button></div>`;
    $('#detail-dialog').showModal();
  }
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3000);}
  function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Download prepared.');}
  function csv(rows){return '\uFEFF'+rows.map(row=>row.map(v=>{let t=String(v??'');if(/^[=+@]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
  function exportData(){
    if(S.view==='sources'){download('india-market-atlas-research.json',JSON.stringify(D,null,2),'application/json');return;}
    if(S.view==='lab'){download('india-market-atlas-scenario.json',JSON.stringify({type:'USER_ASSUMPTIONS_NOT_MEASURED_DATA',market:geoName(),business:S.labBusiness,period:'month',unit:D.businesses.find(b=>b.id===S.labBusiness).unit,assumptions:S.lab,results:calculateLab(),researchSnapshot:D.checked},null,2),'application/json');return;}
    let rows=[];
    if(S.view==='explorer') rows=[['Business','Market selection','Evidence scope','Evidence type','Demand indicator','Supply indicator','Units / measure','Reporting period','Source URL'],...filteredBusinesses().map(b=>{const r=record(b);return [b.name,geoName(),r.scope,evidenceLabel(r)[0],r.demandText,r.supplyText,r.unit||'See business brief',r.period||'Missing',r.source?D.sources[r.source].url:''];})];
    if(S.view==='cities') rows=[['Market','Sector','Transactions','New additions','Units','Period','Transaction/new-addition ratio','Activity index','Flow weight percent','Source URL'],...sortedCities().map(c=>{const p=pair(S.cityMetric,c.id);return [c.name,S.cityMetric,p.demand,p.supply,p.unit,p.period,(p.demand/p.supply).toFixed(4),activityScore(c).toFixed(2),S.cityMetric==='housing'?S.weight:100,D.sources[p.source].url];})];
    if(S.view==='momentum') rows=[['Indicator','Evidence type','Value display','Period','Scope','Note','Source URL'],...signalList().map(r=>[r.title,r.trend,r.display,r.period,r.scope,r.note,D.sources[r.source].url])];
    if(S.view==='trade') rows=[['Flow','Table','Group / country','FY2024-25 USD million','FY2025-26 USD million','Value growth percent','Release vintage','Source URL'],...tradeRows().map(r=>[r[0],'Commodity',r[1],r[2],r[3],((r[3]/r[2]-1)*100).toFixed(2),D.trade.vintage,D.sources.tradeTables.url]),...D.trade.partners.filter(r=>r[0]===S.flow).map(r=>[r[0],'Country (all commodities)',r[1],r[2],r[3],((r[3]/r[2]-1)*100).toFixed(2),D.trade.vintage,D.sources.tradeTables.url])];
    download(`india-market-atlas-${S.view}.csv`,csv(rows),'text/csv;charset=utf-8');
  }
  function resetLab(){S.lab={buyers:1000,frequency:4,providers:20,capacity:150,shock:0,price:50,cost:25,fixed:30000,capture:10};render();}
  document.addEventListener('click',e=>{
    const el=e.target.closest('button');if(!el)return;
    if(el.dataset.view){if($('#detail-dialog').open)$('#detail-dialog').close();navigate(el.dataset.view);return;}
    if(el.dataset.detail){showDetail(el.dataset.detail);return;}
    if(el.dataset.city){S.geo=el.dataset.city;render();return;}
    if(el.dataset.state){S.geo='state:'+el.dataset.state;navigate('explorer');return;}
    if(el.dataset.cityMetric){S.cityMetric=el.dataset.cityMetric;render();return;}
    if(el.dataset.momentum){S.momentum=el.dataset.momentum;render();return;}
    if(el.dataset.flow){S.flow=el.dataset.flow;render();return;}
    const model=el.dataset.labBusiness||el.dataset.tradeModel;
    if(model){S.labBusiness=model;if($('#detail-dialog').open)$('#detail-dialog').close();navigate('lab');return;}
    switch(el.id){case 'method-top':navigate('sources');break;case 'export-data':exportData();break;case 'close-dialog':$('#detail-dialog').close();break;case 'previous-page':S.page--;renderBusinessRows();break;case 'next-page':S.page++;renderBusinessRows();break;case 'reset-filters':S.query='';S.sector='all';S.evidence='all';S.page=1;render();break;case 'reset-lab':resetLab();break;}
  });
  document.addEventListener('change',e=>{
    const el=e.target;
    switch(el.id){case 'geography':S.geo=el.value;S.page=1;render();break;case 'sector-filter':S.sector=el.value;S.page=1;renderBusinessRows();break;case 'evidence-filter':S.evidence=el.value;S.page=1;renderBusinessRows();break;case 'chart-metric':S.cityMetric=el.value;render();break;case 'city-sort':S.citySort=el.value;renderCityRows();break;case 'lab-business':S.labBusiness=el.value;render();break;case 'trade-sort':S.tradeSort=el.value;renderTradeRows();break;}
  });
  document.addEventListener('input',e=>{
    const el=e.target;
    if(el.dataset.lab){const key=el.dataset.lab;S.lab[key]=Number(el.value);$('#value-'+key).textContent=num(S.lab[key],key==='frequency'?1:0)+(['shock','capture'].includes(key)?'%':'');updateLabResult();return;}
    if(el.dataset.money){const v=Number(el.value);if(Number.isFinite(v)&&v>=0&&v<=1e9){S.lab[el.dataset.money]=v;el.setCustomValidity('');updateLabResult();}else{el.setCustomValidity('Enter a number from 0 to 1,000,000,000.');el.reportValidity();}return;}
    switch(el.id){case 'business-search':S.query=el.value;S.page=1;renderBusinessRows();break;case 'index-weight':S.weight=Number(el.value);$('#weight-value').textContent=S.weight+'%';renderCityRows();break;case 'max-age':S.maxAge=Number(el.value);$('#age-value').textContent=S.maxAge+' months';renderSignalCards();break;case 'trade-search':S.tradeQuery=el.value;renderTradeRows();break;case 'trade-min':S.tradeMin=Number(el.value);$('#trade-min-value').textContent=S.tradeMin===-100?'Show all':pct(S.tradeMin,0);renderTradeRows();break;}
  });
  $('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
  window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(viewInfo[v]&&v!==S.view){S.view=v;render();}});
  setupGeography();const initial=location.hash.slice(1);if(viewInfo[initial])S.view=initial;render();
  // Optional browser-native agent interface. Uses the same validated UI actions.
  const mc=document.modelContext;
  if(mc?.registerTool){
    const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
    const tools=[
      {name:'configure_market_explorer',title:'Configure India market explorer',description:'Set a valid geography and search query, then display matching business evidence.',inputSchema:{type:'object',properties:{geography:{type:'string'},query:{type:'string'}},required:['geography'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const valid=['india',...D.cities.map(c=>c.id),...D.states.map(s=>'state:'+s)];if(!input||!valid.includes(input.geography)||('query'in input&&typeof input.query!=='string'))throw new Error('Unknown geography or invalid query.');S.geo=input.geography;S.query=input.query||'';S.sector='all';S.evidence='all';S.page=1;navigate('explorer');return {market:geoName(),count:filteredBusinesses().length,results:filteredBusinesses().slice(0,10).map(b=>({business:b.name,evidence:evidenceLabel(record(b))[0]}))};}},
      {name:'read_visible_market_evidence',title:'Read visible market evidence',description:'Read the current market, view, and matching business evidence without changing state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input&&Object.keys(input).length)throw new Error('No parameters accepted.');return {view:S.view,market:geoName(),checked:D.checked,liveFeeds:false,businesses:filteredBusinesses().map(b=>({id:b.id,name:b.name,...record(b)}))};}}
    ];
    tools.forEach(tool=>{try{Promise.resolve(mc.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch(_){}});
  }
  window.AtlasDiagnostics={calculateLab,record,pair,activityScore,getState:()=>structuredClone(S)};
})();
